// Approved videos go out first, then one new topic per run.
const rows = $input.all().map((item) => item.json);
const statusOf = (row) => String(row.status || '').trim().toLowerCase();

const approved = rows.find((row) => statusOf(row) === 'approved' && row.project_id);
if (approved) {
  return [{ json: { ...approved, action: 'publish' } }];
}

const ready = rows.find((row) => statusOf(row) === 'ready' && String(row.topic || '').trim());
if (ready) {
  return [{ json: { ...ready, action: 'create' } }];
}

return [];

parameters.text:
=You write scripts for faceless vertical short videos (TikTok, Reels, YouTube Shorts).

Topic: {{ $('Pick next job').item.json.topic }}
Audience: {{ $('Pick next job').item.json.audience || 'a general audience' }}
Length: {{ $('Settings').item.json.videoLength }}, language: {{ $('Settings').item.json.language }}

Write 5 to 8 short voiceover lines. Line 1 is a scroll-stopping hook, the last line is a call to action. For every line add a concrete visual note that stock or AI footage can show (no people talking to camera, no on-screen text).
Also write a title under 70 characters, a 1 to 2 sentence caption, and 3 to 6 hashtags without the # sign. Keep the caption and hashtags together under 240 characters, so the post fits X.

parameters.jsonSchemaExample:
{
  "script": [
    {
      "voiceover": "Most people check their phone before they even open their eyes.",
      "visual": "close-up of a phone screen lighting up a dark bedroom"
    },
    {
      "voiceover": "Try this instead: drink a full glass of water first.",
      "visual": "water pouring into a glass in morning sunlight"
    }
  ],
  "title": "3 morning habits that boost focus",
  "caption": "Steal these 3 habits for a sharper morning.",
  "hashtags": [
    "productivity",
    "morningroutine",
    "focus"
  ]
}

