const brief = $json.output;
const s = $('Settings').item.json;
const beats = brief.script
  .map((line, index) => `${index + 1}. Voiceover: "${line.voiceover}" | Visual: ${line.visual}`)
  .join('\n');
const brandNote = s.brandNotes ? `\n- Brand notes: ${s.brandNotes}` : '';
const visuals = {
  ai: 'for each line generate an AI video clip that matches its visual note.',
  hybrid: 'for line 1 (the hook) generate one short AI video clip that matches its visual note. For every other line pick stock footage or a stock image and do not generate more AI media.',
}[s.footage] || 'for each line pick stock footage or a stock image that matches its visual note. Do not generate AI video or AI images.';

const prompt = `Create a vertical 9:16 faceless short video, ${s.videoLength} long, in ${s.language}.
- Narration: an AI voiceover with a ${s.voiceStyle} voice that reads exactly the voiceover lines below, in order.
- Visuals: ${visuals} No talking heads. Keep shots 2 to 4 seconds and cut on the beat of the voiceover.
- Captions: bold animated captions synced word by word to the voiceover, inside the 9:16 safe area.
- Music: subtle background music under the voiceover, faded out at the end.
- Brand: use the workspace brand kit colors, fonts and logo if one exists.${brandNote}
The first line is the hook and must land in the first 2 seconds. End on the last line as the call to action.

Script:
${beats}`;

return [{ json: { prompt, title: brief.title, caption: [brief.caption, brief.hashtags.map((tag) => '#' + tag.replace(/^#/, '')).join(' ')].join('\n\n') } }];
